import { randomUUID } from 'node:crypto';
import {
  ModelConnectionSchema,
  ModelSchema,
  StoredModelConnectionSchema,
} from '@harness/contracts';
import {
  hasCredential,
  readCredential,
  removeCredential,
  writeCredential,
} from './credentials.js';

const SETTING_KEY = 'model-connections';
const REQUEST_TIMEOUT_MS = 12_000;
const MAX_MODEL_RESPONSE_BYTES = 2 * 1024 * 1024;
const MAX_MODEL_PAGES = 20;
const RESPONSE_HEADERS = Object.freeze({ accept: 'application/json' });

const PRESET_LABS = Object.freeze({
  openai: 'OpenAI',
  anthropic: 'Anthropic',
  openrouter: 'OpenRouter',
  kimi: 'Moonshot',
  moonshot: 'Moonshot',
  zai: 'Z.ai',
  deepseek: 'DeepSeek',
  qwen: 'Qwen',
  zhipu: 'Zhipu AI',
  volcengine: 'Volcengine',
  minimax: 'MiniMax',
  baidu: 'Baidu Qianfan',
  tencent: 'Tencent TokenHub',
  siliconflow: 'SiliconFlow',
});

export const MODEL_CONNECTION_CAPABILITIES = Object.freeze({
  streaming: true,
  tools: true,
  images: false,
  reasoning: false,
  modelDiscovery: true,
  usage: false,
});

function safeConnection(connection) {
  const { credentialRef, ...publicConnection } = connection;
  return ModelConnectionSchema.parse({
    ...publicConnection,
    credentialConfigured: hasCredential(credentialRef),
    capabilities: MODEL_CONNECTION_CAPABILITIES,
  });
}

function modelEndpoints(connection) {
  const base = new URL(connection.baseUrl);
  if (connection.modelListUrl) {
    const url = new URL(connection.modelListUrl);
    if (url.origin !== base.origin || url.username || url.password || url.hash)
      throw new Error('model list URL must use the same origin as the API base URL');
    return [{ url, officialDashScope: false }];
  }
  if (!base.pathname.endsWith('/')) base.pathname += '/';
  const url = new URL('models', base);
  const officialDashScope = connection.preset === 'qwen' && url.protocol === 'https:' &&
    url.pathname === '/compatible-mode/v1/models' &&
    (/^[a-z0-9-]+\.[a-z0-9-]+\.maas\.aliyuncs\.com$/u.test(url.hostname) || url.hostname === 'dashscope-us.aliyuncs.com');
  if (officialDashScope) {
    url.pathname = '/api/v1/models';
    url.searchParams.set('capabilities', 'TG');
    url.searchParams.set('page_no', '1');
    url.searchParams.set('page_size', '100');
  }
  if (connection.preset === 'siliconflow' && ['https://api.siliconflow.cn', 'https://api.siliconflow.com'].includes(url.origin)) {
    url.searchParams.set('sub_type', 'chat');
  }
  const candidates = [{ url, officialDashScope }];
  if (officialDashScope || connection.preset === 'siliconflow') return candidates;
  const path = base.pathname.replace(/\/$/u, '');
  const append = pathname => {
    const next = new URL(base);
    next.pathname = pathname;
    if (!candidates.some(candidate => candidate.url.href === next.href))
      candidates.push({ url: next, officialDashScope: false });
  };
  if (!/\/v1$/u.test(path)) append(`${path}/v1/models`);
  const compatRoot = path.replace(/\/(?:api\/(?:anthropic|claudecode|coding)|apps\/anthropic|anthropic|claude|claudecode|coding|step_plan)(?:\/v\d+)?$/u, '');
  if (compatRoot !== path) {
    append(`${compatRoot}/v1/models`);
    append(`${compatRoot}/models`);
  }
  return candidates;
}

function authHeaders(connection, apiKey) {
  if (connection.transport === 'anthropic-messages') {
    return {
      ...RESPONSE_HEADERS,
      'anthropic-version': '2023-06-01',
      'x-api-key': apiKey,
    };
  }
  return { ...RESPONSE_HEADERS, authorization: `Bearer ${apiKey}` };
}

async function readLimitedBody(response) {
  const length = Number(response.headers.get('content-length'));
  if (Number.isFinite(length) && length > MAX_MODEL_RESPONSE_BYTES)
    throw new Error('model provider response is too large');
  if (!response.body) return '';
  const reader = response.body.getReader();
  const chunks = [];
  let size = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > MAX_MODEL_RESPONSE_BYTES) {
        await reader.cancel();
        throw new Error('model provider response is too large');
      }
      chunks.push(Buffer.from(value));
    }
  } finally {
    reader.releaseLock();
  }
  return Buffer.concat(chunks, size).toString('utf8');
}

function modelRecords(payload) {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload?.data)) return payload.data;
  if (Array.isArray(payload?.models)) return payload.models;
  if (Array.isArray(payload?.result)) return payload.result;
  if (Array.isArray(payload?.output?.models)) return payload.output.models;
  throw new Error('model provider returned an unsupported model list');
}

function normalizeModels(connection, records) {
  const unique = new Map();
  for (const record of records) {
    if (connection.preset === 'tencent' && record?.status && record.status !== 'online') continue;
    if (connection.preset === 'baidu' && record?.status === 'offline') continue;
    if (connection.preset === 'volcengine' && Array.isArray(record?.task_type) && record.task_type.length &&
        !record.task_type.includes('TextGeneration')) continue;
    const idValue = typeof record === 'string'
      ? record
      : record && typeof record === 'object'
        ? record.id ?? record.model ?? record.model_id ?? record.name
        : undefined;
    if (typeof idValue !== 'string' || !idValue.trim()) continue;
    const id = idValue.trim();
    if (unique.has(id)) continue;
    const rawName = typeof record === 'object' && record !== null
      ? record.display_name ?? record.displayName ?? record.name
      : undefined;
    const displayName = typeof rawName === 'string' && rawName.trim() ? rawName.trim() : id;
    const model = ModelSchema.parse({
      id,
      displayName,
      isDefault: connection.defaultModel === id,
      reasoningEfforts: ['auto', 'low', 'medium', 'high'],
      defaultReasoningEffort: 'auto',
      serviceTiers: [],
      ...(PRESET_LABS[connection.preset] ? { lab: PRESET_LABS[connection.preset] } : {}),
    });
    unique.set(id, model);
  }
  return [...unique.values()];
}

async function readModelsPage(fetchImpl, url, headers, signal) {
  let response;
  try {
    response = await fetchImpl(url, { method: 'GET', headers, redirect: 'error', signal });
  } catch {
    if (signal.aborted) throw new Error('model provider request timed out');
    throw new Error('could not reach the model provider');
  }
  if (!response.ok) {
    await response.body?.cancel().catch(() => {});
    if ([404, 405, 501].includes(response.status)) {
      const error = new Error('model provider does not offer a model list');
      error.code = 'MODEL_LIST_UNAVAILABLE';
      throw error;
    }
    throw new Error(`model provider returned HTTP ${response.status}`);
  }
  const body = await readLimitedBody(response).catch(error => {
    if (signal.aborted) throw new Error('model provider request timed out');
    throw error;
  });
  try {
    return JSON.parse(body);
  } catch {
    throw new Error('model provider returned invalid JSON');
  }
}

export async function discoverConnectionModels(connection, apiKey, fetchImpl = globalThis.fetch) {
  const headers = authHeaders(connection, apiKey);
  const signal = AbortSignal.timeout(REQUEST_TIMEOUT_MS);
  for (const candidate of modelEndpoints(connection)) {
    try {
      return await readModelCatalog(connection, candidate, headers, signal, fetchImpl);
    } catch (error) {
      if (error?.code !== 'MODEL_LIST_UNAVAILABLE') throw error;
    }
  }
  throw new Error('model provider does not offer a model list');
}

async function readModelCatalog(connection, { url, officialDashScope }, headers, signal, fetchImpl) {
  const cursors = new Set();
  const records = [];
  for (let page = 1; page <= MAX_MODEL_PAGES; page++) {
    const payload = await readModelsPage(fetchImpl, new URL(url), headers, signal);
    const items = modelRecords(payload);
    records.push(...items);
    if (officialDashScope && payload.output) {
      const { total, page_size: pageSize } = payload.output;
      if (Number.isSafeInteger(total) && Number.isSafeInteger(pageSize) && pageSize > 0 && page * pageSize < total) {
        if (!items.length) throw new Error('model provider returned an invalid pagination page');
        url.searchParams.set('page_no', String(page + 1));
        continue;
      }
    } else if (connection.transport === 'anthropic-messages' && payload.has_more === true) {
      const cursor = payload.last_id;
      if (typeof cursor !== 'string' || !cursor || cursors.has(cursor))
        throw new Error('model provider returned an invalid pagination cursor');
      cursors.add(cursor);
      url.searchParams.set('after_id', cursor);
      continue;
    }
    return { models: normalizeModels(connection, records) };
  }
  throw new Error('model provider returned too many model pages');
}

export class ModelConnectionService {
  #store;

  constructor(store) {
    this.#store = store;
  }

  #stored() {
    return this.#store.modelConnections().map((value) => StoredModelConnectionSchema.parse(value));
  }

  #find(connectionId) {
    return this.#stored().find((connection) => connection.id === connectionId);
  }

  list() {
    return { connections: this.#stored().map(safeConnection) };
  }

  upsert(input) {
    const connection = ModelConnectionSchema.omit({
      credentialConfigured: true,
      capabilities: true,
      problem: true,
    }).parse(input);
    if (connection.modelListUrl) modelEndpoints(connection);
    const existing = this.#find(connection.id);
    const sameOrigin = existing && new URL(existing.baseUrl).origin === new URL(connection.baseUrl).origin;
    const stored = StoredModelConnectionSchema.parse({
      ...connection,
      credentialRef: sameOrigin ? existing.credentialRef : `model-connection-${randomUUID()}`,
    });
    const next = this.#stored().filter((item) => item.id !== stored.id);
    next.push(stored);
    this.#store.updateModelConnections(next);
    if (existing && !sameOrigin) removeCredential(existing.credentialRef);
    return { connection: safeConnection(stored) };
  }

  setCredential(connectionId, apiKey) {
    const connection = this.#find(connectionId);
    if (!connection) throw new Error('model connection was not found');
    const secret = apiKey.trim();
    if (!secret || /[\r\n]/u.test(secret)) throw new Error('API key must be a single non-empty line');
    writeCredential(connection.credentialRef, secret);
    return { credentialConfigured: true };
  }

  remove(connectionId) {
    const current = this.#stored();
    const removed = current.find((connection) => connection.id === connectionId);
    if (!removed) return {};
    this.#store.updateModelConnections(current.filter((connection) => connection.id !== connectionId));
    removeCredential(removed.credentialRef);
    return {};
  }

  /** Server-internal only: resolves a chat runtime's selected connection and secret. */
  resolveForRuntime(connectionId) {
    const connection = this.#find(connectionId);
    if (!connection) throw new Error('model connection was not found');
    if (!connection.enabled) throw new Error('model connection is disabled');
    let apiKey;
    try {
      apiKey = readCredential(connection.credentialRef);
    } catch {
      throw new Error('API key is not configured for this model connection');
    }
    const { credentialRef, ...configuration } = connection;
    return { ...configuration, apiKey };
  }

  async models(connectionId) {
    const { apiKey, ...connection } = this.resolveForRuntime(connectionId);
    return discoverConnectionModels(connection, apiKey);
  }

  async previewModels({ connectionId, apiKey, ...draft }, fetchImpl = globalThis.fetch) {
    let secret = apiKey?.trim();
    if (!secret && connectionId) {
      const saved = this.#find(connectionId);
      if (saved && new URL(saved.baseUrl).origin === new URL(draft.baseUrl).origin) {
        try { secret = readCredential(saved.credentialRef); } catch { /* Missing keys are handled below. */ }
      }
    }
    if (!secret) throw new Error('API key is not configured for this model connection');
    if (/[\r\n]/u.test(secret)) throw new Error('API key must be a single non-empty line');
    return discoverConnectionModels(draft, secret, fetchImpl);
  }
}

export { SETTING_KEY as MODEL_CONNECTIONS_SETTING_KEY };
